document.addEventListener('DOMContentLoaded',()=>{
 const trigger=document.querySelector('.mobile-toggle');
 const panel=document.querySelector('.mobile-nav');
 const hero=document.querySelector('.hero');
 const floatCTA=document.querySelector('.floating-book');
 const setMenu=(open)=>{
   if(!trigger||!panel)return;
   trigger.setAttribute('aria-expanded',String(open));
   trigger.setAttribute('aria-label',open?trigger.dataset.labelClose:trigger.dataset.labelOpen);
   panel.hidden=!open;
   document.documentElement.classList.toggle('menu-open',open);
   if(floatCTA)floatCTA.classList.toggle('menu-blocked',open);
 };
 if(trigger&&panel){
   trigger.addEventListener('click',()=>setMenu(trigger.getAttribute('aria-expanded')!=='true'));
   panel.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>setMenu(false)));
   document.addEventListener('keydown',e=>{if(e.key==='Escape'&&trigger.getAttribute('aria-expanded')==='true'){setMenu(false);trigger.focus()}});
   document.addEventListener('pointerdown',e=>{
     if(trigger.getAttribute('aria-expanded')==='true'&&!trigger.contains(e.target)&&!panel.contains(e.target))setMenu(false);
   });
   window.addEventListener('resize',()=>{if(window.innerWidth>950)setMenu(false)},{passive:true});
 }
 if(hero&&floatCTA){
   const mobile=()=>window.matchMedia('(max-width:780px)').matches;
   const update=()=>{
     const r=hero.getBoundingClientRect();
     floatCTA.classList.toggle('is-visible',mobile()&&r.bottom<=window.innerHeight*.35);
   };
   if('IntersectionObserver'in window){
     const observer=new IntersectionObserver(update,{threshold:[0,.2,.8,1]});
     observer.observe(hero);
   }
   window.addEventListener('scroll',update,{passive:true});
   window.addEventListener('resize',update,{passive:true});
   update();
 }
});